SELECT id, service, host, log_ts, level, latency_ms, status_code, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['trace'] AS trace, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE latency_ms > 864;
